(()=>{'use strict';if(new URLSearchParams(location.search).has('pair'))return;
const box=document.createElement('section');box.className='field-import panel';box.setAttribute('aria-labelledby','fieldImportTitle');box.innerHTML='<h2 id="fieldImportTitle">ผลวัดสัญญาณจากหน้างานจริง</h2><p>นำเข้า LAT, LONG และ RSSI เพื่อแสดงจุดสีบนแผนที่ได้ทันที ไม่ต้องกรอกพิกัดแม่ข่าย</p><div class="field-import-actions"><button id="fieldImportChoose" type="button" class="secondary">＋ เพิ่มไฟล์ Excel / CSV</button><input id="fieldImportFile" type="file" accept=".xlsx,.csv,.xls" hidden aria-label="เลือกไฟล์ผลวัดหน้างาน"><button id="fieldImportRemove" type="button" class="secondary" hidden>นำไฟล์ออก</button><button id="fieldFit" type="button" class="secondary" disabled>ดูจุดทั้งหมดบนแผนที่</button><button id="fieldKmz" type="button" class="secondary" disabled>Export จุดลูกข่าย KMZ</button><label><input id="fieldVisible" type="checkbox" checked> แสดงจุดผลวัดจริง</label></div><p id="fieldImportStatus" role="status" aria-live="polite">ยังไม่ได้เลือกไฟล์</p><p class="hint">อ่าน XLSX / CSV ในเครื่อง ไม่ส่งไฟล์ขึ้นเซิร์ฟเวอร์ · ใช้สี RSSI ชุดเดียวกับ Sim · จุดขอบขาว–ดำคือผลวัดจริง · ต่ำกว่า −105 dBm แสดงสีเทาเพื่อคงตำแหน่ง · ยังไม่ประเมินความคลาดเคลื่อน · โหลดหน้าใหม่ต้องเลือกไฟล์ใหม่</p><div id="fieldLegend" hidden></div>';
const main=document.querySelector('main');(main.querySelector('.intro')||main.firstElementChild).after(box);const $=id=>document.getElementById(id),file=$('fieldImportFile'),status=$('fieldImportStatus'),remove=$('fieldImportRemove'),fit=$('fieldFit'),visible=$('fieldVisible');let points=[],revision=0;
const frame=document.querySelector('.mapframe'),ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.classList.add('field-points');svg.setAttribute('aria-label','จุดผลวัดสัญญาณหน้างาน');frame.append(svg);
const detail=document.createElement('div');detail.className='field-point-detail';detail.hidden=true;detail.setAttribute('role','status');frame.parentElement.after(detail);
function show(p){detail.replaceChildren();const title=document.createElement('b');title.textContent=p.name;detail.append(title);for(const text of ['RSSI วัดจริง: '+p.rssi+' dBm','พิกัด: '+p.lat.toFixed(6)+', '+p.lon.toFixed(6),RFFieldMap.bearingLabel(p.lat,p.lon),...(p.base?['แม่ข่ายที่ระบุในไฟล์: '+p.base]:[]),'แถวต้นฉบับ: '+p.row]){const div=document.createElement('div');div.textContent=text;detail.append(div)}const message=RFFieldMap.selectReceiver(p.lat,p.lon);if(message){const note=document.createElement('div');note.textContent=message;detail.append(note)}detail.hidden=false}
function draw(){svg.replaceChildren();if(!visible.checked||!points.length)return;const w=frame.clientWidth,h=frame.clientHeight;svg.setAttribute('viewBox','0 0 '+w+' '+h);for(const p of points){const s=RFFieldMap.screen(p.lat,p.lon);if(s.x< -12||s.x>w+12||s.y< -12||s.y>h+12)continue;const g=document.createElementNS(ns,'g');g.setAttribute('transform','translate('+s.x+' '+s.y+')');g.classList.add('field-marker');g.setAttribute('tabindex','0');g.setAttribute('role','button');g.setAttribute('aria-label',p.name+' RSSI '+p.rssi+' dBm');for(const [radius,fill,stroke,width] of [[8,'#fff','#111827',2],[5.5,RFFieldMap.color(p.rssi),'#fff',1]]){const c=document.createElementNS(ns,'circle');c.setAttribute('r',radius);c.setAttribute('fill',fill);c.setAttribute('stroke',stroke);c.setAttribute('stroke-width',width);g.append(c)}const title=document.createElementNS(ns,'title');title.textContent=p.name+' · '+p.rssi+' dBm';g.append(title);g.onclick=e=>{e.stopPropagation();show(p)};g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show(p)}};svg.append(g)}}globalThis.RFFieldLayer={exportData:()=>RFFieldKMZ.build(points,visible.checked),draw,description:()=>points.length?'ผลวัดจริง '+points.length+' จุด · ไม่ต้องมีพิกัดแม่ข่าย':''};
$('fieldLegend').innerHTML=[['≥ −45','#0000ff'],['−55 ถึง < −45','#00a9fe'],['−65 ถึง < −55','#00fea9'],['−75 ถึง < −65','#00fe00'],['−85 ถึง < −75','#a9fe00'],['−95 ถึง < −85','#fea900'],['−105 ถึง < −95','#ff0000'],['< −105','#64748b']].map(([t,c])=>'<span><i style="background:'+c+'"></i>'+t+' dBm</span>').join('');
$('fieldKmz').onclick=()=>{try{const data=RFFieldKMZ.build(points,visible.checked),blob=RFFieldZip([['doc.kml',new TextEncoder().encode('<?xml version="1.0" encoding="UTF-8"?><kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>ผลวัด RSSI ลูกข่าย</name>'+data.kml+'</Document></kml>')],...data.files]),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='rf-field-rssi.kmz';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);status.textContent='ส่งออก KMZ ลูกข่าย '+points.length+' จุดแล้ว · รวมทุกจุด พร้อมสี RSSI และรายละเอียด'}catch(e){status.textContent='ส่งออก KMZ ไม่สำเร็จ: '+e.message}};
$('fieldImportChoose').onclick=()=>file.click();file.onchange=async()=>{const f=file.files[0];if(!f)return;const token=++revision;status.textContent='กำลังอ่านไฟล์…';try{const data=await RFFieldReader.read(f);if(token!==revision)return;points=data.points;visible.checked=true;remove.hidden=false;fit.disabled=false;$('fieldKmz').disabled=false;$('fieldLegend').hidden=false;detail.hidden=true;status.textContent=f.name+' · ชีต '+data.sheet+' · '+points.length+' จุด'+(data.skipped.length?' · ข้าม '+data.skipped.length+' แถวที่ไม่มีพิกัด/RSSI ถูกต้อง':'')+' · อ่านแล้ว ไม่ได้ประเมินความคลาดเคลื่อน';if($('basemap').value!=='osm'){$('basemap').value='osm';$('basemap').dispatchEvent(new Event('change'))}RFFieldMap.fit(points)}catch(e){if(token!==revision)return;status.textContent='อ่านไม่ได้: '+e.message+(points.length?' · ยังคงจุดจากไฟล์เดิม':'');file.value=''}};
remove.onclick=()=>{revision++;points=[];file.value='';remove.hidden=true;fit.disabled=true;$('fieldKmz').disabled=true;$('fieldLegend').hidden=true;detail.hidden=true;status.textContent='ยังไม่ได้เลือกไฟล์';draw()};fit.onclick=()=>{RFFieldMap.fit(points);$('map').scrollIntoView({block:'center',behavior:'smooth'})};visible.onchange=()=>{detail.hidden=true;draw()};
})();
